/* ---------- Ask, in the window: a replay of a real chat with kalypso ---------- */
(function askDemo() {
  const panel = $('.panel[data-panel="ask"]');
  if (!panel) return;
  const orb = makeOrb($(".demo-orb"), 112);
  const start = $("#ad-start"), log = $("#ad-log"), text = $("#ad-text"), status = $("#ask-status");
  const ASK = "The login test is flaky on CI and the README is out of date. Can you sort both out?";
  // [kind, text, wait ms after]
  const RUN = [
    ["user", ASK, 900],
    ["text", "Two separate jobs, so I'll run them in parallel: <b>coder</b> takes the flaky test, and a new <b>writer</b> agent updates the README.", 1100],
    ["tool", "kx-agent|list", 600],
    ["tool", "kx-agent|create writer --role \"Keeps the docs accurate\"", 700],
    ["tool", "kx-agent|send coder \"tests/auth/login.test.ts fails 1 in 7 runs…\" --wait 0", 650],
    ["tool", "kx-agent|send writer \"Update the install steps in README.md…\" --wait 0", 650],
    ["tool", "kx-agent|wait coder", 1500],
    ["tool", "kx-agent|wait writer", 1200],
    ["text", "Both are done. <b>coder</b> fixed the flaky test: it checked the URL before the redirect finished, and now 20 of 20 runs pass. <b>writer</b> rewrote the README's install section for Docker and Podman.", 1200],
    ["done", "Done · 9 turns · $0.05", 5200],
  ];
  const esc = (t) => t.replace(/&/g, "&amp;").replace(/</g, "&lt;");
  let timers = [], running = false, inView = false;
  const later = (ms, fn) => timers.push(setTimeout(fn, ms));
  const clear = () => { timers.forEach(clearTimeout); timers = []; };
  const setStatus = (t, done) => { status.lastChild.textContent = t; status.classList.toggle("done", !!done); };
  const add = ([kind, t]) => {
    const li = document.createElement("li");
    li.className = `ad-${kind} new`;
    if (kind === "tool") { const [tool, arg] = t.split("|"); li.innerHTML = `<i>Bash</i><b>${tool}</b> ${esc(arg)}`; }
    else li.innerHTML = kind === "text" ? t : esc(t);
    log.append(li);
    log.scrollTop = log.scrollHeight;
  };
  const play = () => {
    clear(); running = true;
    log.replaceChildren(); text.textContent = ""; start.classList.remove("gone"); setStatus("Ready");
    orb.active(false);
    // Type the request: the orb takes every keystroke.
    let t = 1400;
    for (let k = 1; k <= ASK.length; k++) later((t += 38 + (k % 7 === 0 ? 70 : 0)), () => { text.textContent = ASK.slice(0, k); orb.beat(); });
    // Send: the start screen gives way to the conversation.
    later((t += 500), () => { orb.kick(); orb.active(true); });
    later((t += 700), () => { start.classList.add("gone"); text.textContent = ""; setStatus("Working"); });
    for (const r of RUN) { later((t += 120), () => add(r)); t += r[2]; if (r[0] === "done") later(t - r[2] + 130, () => setStatus("Waiting for a message", true)); }
    later(t, () => { running = false; if (inView && panel.classList.contains("on")) play(); });
  };
  const check = () => {
    const on = inView && panel.classList.contains("on");
    if (on && !running) play();
    if (!on && running) { clear(); running = false; }
  };
  if (reduce) { start.classList.add("gone"); RUN.forEach(add); setStatus("Waiting for a message", true); return; }
  new IntersectionObserver(([e]) => { inView = e.isIntersecting; check(); }, { threshold: 0.35 }).observe(panel.closest(".win"));
  new MutationObserver(check).observe(panel, { attributes: true, attributeFilter: ["class"] });
})();

/* ---------- Layers: assemble on scroll, depth under the cursor ---------- */
(function layersMotion() {
  const isle = $(".isle"), map = $("#isle");
  if (!isle || !map) return;
  const order = ["sandbox", "policies", "vault", "gateway"];
  const plates = order.map((k) => map.querySelector(`[data-layer="${k}"]`)).filter(Boolean);
  plates.forEach((p, k) => p.style.setProperty("--d", k));
  if (reduce) return;
  // Pressed together in the middle until the figure is in view, then spread into the stack.
  // Plates sit ~100 units apart around the middle.
  const mid = (plates.length - 1) / 2;
  const spread = (s) => {
    const k = 1 - s;
    // CSS translations on SVG shapes are in the drawing's own units, so no scaling is needed.
    plates.forEach((p, i) => p.style.setProperty("--gap", `${((i - mid) * 100 * 0.82 * k).toFixed(1)}px`));
    map.style.setProperty("--labels", Math.max(0, (s - 0.55) / 0.45).toFixed(2));
  };
  spread(0);
  const steps = Array.from({ length: 31 }, (_, i) => i / 30);
  new IntersectionObserver(([e]) => spread(Math.min(1, e.intersectionRatio * 1.7)), { threshold: steps }).observe(map);
  // Depth: each plate follows the cursor by a different amount.
  if (matchMedia("(pointer: fine)").matches) {
    isle.addEventListener("pointermove", (e) => {
      const b = isle.getBoundingClientRect();
      map.style.setProperty("--mx", (((e.clientX - b.left) / b.width) * 2 - 1).toFixed(3));
      map.style.setProperty("--my", (((e.clientY - b.top) / b.height) * 2 - 1).toFixed(3));
    });
    isle.addEventListener("pointerleave", () => { map.style.setProperty("--mx", 0); map.style.setProperty("--my", 0); });
  }
})();

/* ---------- The footer watermark: "kalypso" in dots, a light passing over it ---------- */
(function watermark() {
  const cv = document.getElementById("wm");
  if (!cv) return;
  const ctx = cv.getContext("2d");
  const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
  const WORD = "kalypso";
  // A sweep from warm paper, through the site's blue, to silver.
  let STOPS;
  const stops = () => (STOPS = document.documentElement.classList.contains("white")
    ? [[0, [60, 60, 66]], [0.38, [98, 116, 255]], [0.62, [75, 94, 252]], [1, [110, 114, 128]]]
    : [[0, [233, 231, 225]], [0.38, [140, 150, 255]], [0.62, [75, 94, 252]], [1, [184, 189, 201]]]);
  stops();
  addEventListener("themechange", () => { stops(); build(); });
  const colorAt = (t) => {
    for (let i = 1; i < STOPS.length; i++) {
      if (t <= STOPS[i][0]) {
        const [a, ca] = STOPS[i - 1], [b, cb] = STOPS[i], k = (t - a) / (b - a);
        return ca.map((v, j) => Math.round(v + (cb[j] - v) * k));
      }
    }
    return STOPS[STOPS.length - 1][1];
  };
  let W = 0, H = 0, dpr = 1, step = 6, dots = [], raf = 0, visible = false, t0 = performance.now();
  let mx = -1e5, my = -1e5;

  const build = async () => {
    try { await document.fonts.ready; } catch (e) { /* draw with what's there */ }
    dpr = Math.min(2, devicePixelRatio || 1);
    W = cv.parentElement.clientWidth;
    // The letters fill the width; the canvas shows their top two thirds, cropping the tails.
    const off = document.createElement("canvas"), o = off.getContext("2d");
    let size = 100;
    o.font = `600 ${size}px Geist, system-ui, sans-serif`;
    size = Math.floor(size * (W * 0.98) / o.measureText(WORD).width);
    H = Math.round(size * 0.78);
    step = Math.max(3, Math.round(size / 46));
    off.width = W; off.height = Math.round(size * 1.1);
    o.font = `600 ${size}px Geist, system-ui, sans-serif`;
    o.textBaseline = "alphabetic"; o.fillStyle = "#000";
    o.fillText(WORD, (W - o.measureText(WORD).width) / 2, size * 0.86);
    const px = o.getImageData(0, 0, off.width, off.height).data;
    dots = [];
    for (let y = step / 2; y < H; y += step) {
      for (let x = step / 2; x < W; x += step) {
        if (px[(Math.floor(y) * off.width + Math.floor(x)) * 4 + 3] > 120) dots.push({ x, y, c: colorAt(x / W) });
      }
    }
    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
    cv.style.width = W + "px"; cv.style.height = H + "px";
    draw(performance.now());
  };

  const draw = (now) => {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, W, H);
    const base = step * 0.36;
    // The light crosses every 7 seconds, then rests a moment.
    const phase = reduce ? 0.5 : ((now - t0) % 7000) / 5200;
    const lx = -0.15 * W + phase * 1.3 * W, band = W * 0.12;
    const R = step * 9, R2 = R * R;
    for (const d of dots) {
      const lit = Math.exp(-((d.x - lx) ** 2) / (2 * band * band));
      let x = d.x, y = d.y, push = 0;
      const dx = x - mx, dy = y - my, q = dx * dx + dy * dy;
      if (q < R2) { const dist = Math.sqrt(q) || 1, f = 1 - dist / R; push = f; x += (dx / dist) * f * step * 1.6; y += (dy / dist) * f * step * 1.6; }
      const r = base * (0.7 + 0.55 * lit + 0.6 * push);
      const a = (document.documentElement.classList.contains("white") ? 0.78 : 0.5) + 0.5 * lit + 0.3 * push;
      ctx.fillStyle = `rgba(${d.c[0]},${d.c[1]},${d.c[2]},${Math.min(1, a)})`;
      ctx.beginPath(); ctx.arc(x, y, r, 0, 6.2832); ctx.fill();
    }
  };

  const loop = (now) => { raf = 0; if (!visible) return; draw(now); raf = requestAnimationFrame(loop); };
  const start = () => { if (!raf && !reduce && visible) raf = requestAnimationFrame(loop); };
  const point = (e) => { const b = cv.getBoundingClientRect(); mx = e.clientX - b.left; my = e.clientY - b.top; };
  cv.addEventListener("pointermove", point, { passive: true });
  cv.addEventListener("pointerdown", point, { passive: true });
  for (const ev of ["pointerleave", "pointercancel", "pointerup"]) cv.addEventListener(ev, () => { mx = my = -1e5; }, { passive: true });
  new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible) start(); }).observe(cv);
  let rs = 0;
  new ResizeObserver(() => { clearTimeout(rs); rs = setTimeout(build, 120); }).observe(cv.parentElement);
  build();
})();

/* ---------- See it work: the real app, sample data, anything you'd change asks you to download ---------- */
(function live() {
  const box = $("#live"), frame = $("#live-frame"), screen = $(".live-screen"), startBtn = $("#live-start"), gate = $("#live-gate");
  if (!box || !frame) return;
  const W = 1280, H = 800;
  const big = matchMedia("(min-width: 900px)");
  const fit = () => { const s = Math.min(1, screen.clientWidth / W); screen.style.setProperty("--s", s); screen.style.height = `${Math.round(H * s)}px`; };
  new ResizeObserver(fit).observe(screen);
  fit();
  const load = () => {
    if (frame.src || !big.matches) return;
    frame.src = frame.dataset.src;
    frame.addEventListener("load", () => box.classList.add("ready"), { once: true });
  };
  startBtn.addEventListener("click", load);
  new IntersectionObserver(([e]) => { if (e.isIntersecting) load(); }, { rootMargin: "400px 0px" }).observe(box);
  big.addEventListener?.("change", load);
  addEventListener("themechange", () => {
    const poster = document.documentElement.classList.contains("white") ? "assets/tour-poster-paper.webp" : "assets/tour-poster.webp";
    $$("img, source", startBtn).forEach((el) => (el.tagName === "IMG" ? (el.src = poster) : (el.srcset = poster)));
    if (frame.src) { box.classList.remove("ready"); frame.addEventListener("load", () => box.classList.add("ready"), { once: true }); frame.contentWindow.location.reload(); }
  });
  const close = () => { gate.hidden = true; box.classList.remove("gated"); };
  addEventListener("message", (e) => {
    if (e.origin !== location.origin || e.source !== frame.contentWindow || e.data?.kalypsoDemo !== "download") return;
    gate.hidden = false; box.classList.add("gated");
  });
  $("#live-gate-close").addEventListener("click", close);
  gate.addEventListener("click", (e) => { if (e.target === gate) close(); });
  addEventListener("keydown", (e) => { if (e.key === "Escape" && !gate.hidden) close(); });
  $("#live-gate .btn.primary").addEventListener("click", close);
})();

/* ---------- Follow a call: pick what the agent does, watch each layer decide ---------- */
(function trace() {
  const box = $("#trace");
  if (!box) return;
  const cv = $("#trace-cv"), ctx = cv.getContext("2d"), field = $(".trace-field", box);
  const cmdEl = $("#trace-cmd"), out = $("#trace-out"), gates = $$(".trace-gates li", box), picks = $$(".trace-pick button", box);
  // [verdict, note] per gate; verdicts: pass, skip, block, ask, give, swap, meter.
  const CALLS = {
    tests: { cmd: "npm test", steps: [["pass", "inside /work"], ["pass", "allowed"], ["skip", "no secret needed"], ["skip", "no model call"], ["done", "24 passing"]], out: "It runs in coder's own sandbox. Nothing else on your machine is in reach." },
    push: { cmd: "git push --force origin main", steps: [["pass", "inside /work"], ["block", "No force-push to main"]], out: "Stopped before it ran. coder is told why, and pushes a branch instead." },
    host: { cmd: "curl https://api.unknown.dev/v1", steps: [["pass", "through the egress proxy"], ["ask", "Ask before unknown hosts"], ["skip", "no secret needed"], ["skip", "no model call"], ["done", "200 OK"]], out: "It waits for you. Approve it once, always, or never." },
    secret: { cmd: "gh pr create --fill", steps: [["pass", "inside /work"], ["pass", "allowed"], ["give", "GITHUB_TOKEN, as a file"], ["skip", "no model call"], ["done", "pull request #482"]], out: "The token arrives as a file in /run/kalypso/secrets. It never enters a prompt, so no model ever sees it." },
    model: { cmd: "POST /anthropic/v1/messages  key: kx_7f…", steps: [["pass", "only the gateway is reachable"], ["pass", "allowed"], ["swap", "kx_ key → your real key"], ["meter", "$0.012 · $3.82 left today"], ["done", "Claude Sonnet 5.5"]], out: "The agent holds a stand-in key. Your real key is added at the gateway, after secrets are scrubbed from the request." },
    cap: { cmd: "POST /openai/v1/chat/completions", steps: [["pass", "only the gateway is reachable"], ["pass", "allowed"], ["swap", "kx_ key → your real key"], ["block", "Daily cap of $5.00 reached"]], out: "Stopped at the gateway. It never reaches the provider, so it costs nothing." },
  };
  const ORDER = Object.keys(CALLS);
  const DARK = { grid: "rgba(246,244,239,0.07)", gate: "rgba(246,244,239,0.22)", path: "rgba(246,244,239,0.28)", pass: "#f6f4ef", block: "#ff5a4e", ask: "#f6c445", ink: "#f6f4ef", trail: "246,244,239" };
  const LIGHT = { grid: "rgba(16,16,16,0.08)", gate: "rgba(16,16,16,0.22)", path: "rgba(16,16,16,0.3)", pass: "#101010", block: "#e5382d", ask: "#c98a00", ink: "#101010", trail: "16,16,16" };
  let C = DARK;
  const mode = () => { C = document.documentElement.classList.contains("white") ? LIGHT : DARK; };
  mode();
  addEventListener("themechange", () => { mode(); if (pk && !pk.c) pk.c = null; paint(); });
  let W = 0, H = 0, dpr = 1, horiz = true, pts = [], lit = [], cur = null, timers = [], raf = 0, visible = false, chosen = false;
  let pk = null, bits = [], trail = [];

  const layout = () => {
    dpr = Math.min(2, devicePixelRatio || 1);
    W = field.clientWidth; H = field.clientHeight;
    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
    cv.style.width = W + "px"; cv.style.height = H + "px";
    horiz = W >= 720;
    const fb = field.getBoundingClientRect();
    pts = gates.map((g) => { const b = g.getBoundingClientRect(); return horiz ? [b.left - fb.left + b.width / 2, H * 0.5] : [22, b.top - fb.top + b.height / 2]; });
    pts.unshift(horiz ? [0, H * 0.5] : [22, 0]);
    paint();
  };
  const dot = (x, y, r, c) => { ctx.fillStyle = c; ctx.beginPath(); ctx.arc(x, y, r, 0, 6.2832); ctx.fill(); };
  const paint = () => {
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0); ctx.clearRect(0, 0, W, H);
    const s = 16;
    for (let y = s / 2; y < H; y += s) for (let x = s / 2; x < W; x += s) dot(x, y, 1, C.grid);
    // The path, then each gate as a line of dots, lit by its verdict.
    const [sx, sy] = pts[0], [ex, ey] = pts[pts.length - 1];
    for (let t = 0; t <= 1; t += 6 / Math.max(1, Math.hypot(ex - sx, ey - sy))) dot(sx + (ex - sx) * t, sy + (ey - sy) * t, 1.3, C.path);
    for (let i = 1; i < pts.length; i++) {
      const v = lit[i - 1], c = v === "block" ? C.block : v === "ask" ? C.ask : v && v !== "skip" ? C.pass : C.gate;
      const r = v && v !== "skip" ? 2.1 : 1.5;
      if (horiz) for (let y = 10; y < H - 4; y += 8) dot(pts[i][0], y, r, c);
      else for (let x = 8; x < 44; x += 8) dot(x, pts[i][1], r, c);
    }
    for (const t of trail) dot(t[0], t[1], 2 * t[2], `rgba(${C.trail},${t[2] * 0.5})`);
    if (pk) for (let k = 0; k < 7; k++) { const a = (k / 6) * 6.2832 + pk.t * 3; dot(pk.x + (k ? Math.cos(a) * 5.5 : 0), pk.y + (k ? Math.sin(a) * 5.5 : 0), k ? 2 : 2.6, pk.c || C.ink); }
    for (const b of bits) dot(b.x, b.y, 2, `rgba(255,90,78,${b.a})`);
  };
  const tick = (now) => {
    raf = 0;
    if (pk && pk.to) {
      const k = Math.min(1, (now - pk.t0) / pk.dur), e = k < 0.5 ? 2 * k * k : 1 - (-2 * k + 2) ** 2 / 2;
      pk.x = pk.from[0] + (pk.to[0] - pk.from[0]) * e; pk.y = pk.from[1] + (pk.to[1] - pk.from[1]) * e;
      trail.push([pk.x, pk.y, 1]);
      if (k >= 1) { pk.to = null; pk.done?.(); }
    }
    if (pk) pk.t = now / 1000;
    trail.forEach((t) => (t[2] -= 0.06)); trail = trail.filter((t) => t[2] > 0);
    bits.forEach((b) => { b.x += b.vx; b.y += b.vy; b.vy += 0.12; b.a -= 0.018; }); bits = bits.filter((b) => b.a > 0);
    paint();
    if (visible && (pk || trail.length || bits.length)) raf = requestAnimationFrame(tick);
  };
  const go = () => { if (!raf && visible) raf = requestAnimationFrame(tick); };
  const later = (ms, fn) => timers.push(setTimeout(fn, ms));
  const move = (to, dur, done) => { pk.from = [pk.x, pk.y]; pk.to = to; pk.t0 = performance.now(); pk.dur = dur; pk.done = done; go(); };
  const verdict = (i, [v, note]) => {
    lit[i] = v; const g = gates[i];
    g.dataset.v = v; $("em", g).textContent = note;
  };
  const reset = () => {
    timers.forEach(clearTimeout); timers = []; lit = []; bits = []; trail = []; pk = null;
    gates.forEach((g) => { delete g.dataset.v; $("em", g).textContent = ""; });
    out.textContent = ""; out.classList.remove("on"); cmdEl.textContent = "";
  };
  const play = (id) => {
    reset(); cur = id; box.dataset.call = id;
    picks.forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.call === id)));
    const c = CALLS[id];
    if (reduce || !visible) {
      cmdEl.textContent = c.cmd; c.steps.forEach((s, i) => verdict(i, s)); out.textContent = c.out; out.classList.add("on");
      const last = c.steps.length - 1; pk = { x: pts[last + 1][0], y: pts[last + 1][1], t: 0, c: c.steps[last][0] === "block" ? C.block : C.ink };
      paint(); return;
    }
    let t = 200;
    for (let k = 1; k <= c.cmd.length; k++) later((t += 26), () => { cmdEl.textContent = c.cmd.slice(0, k); });
    later((t += 300), () => {
      pk = { x: pts[0][0], y: pts[0][1], t: 0 };
      const step = (i) => {
        if (i >= c.steps.length) { out.textContent = c.out; out.classList.add("on"); later(4200, () => { if (!chosen) play(ORDER[(ORDER.indexOf(id) + 1) % ORDER.length]); }); return; }
        const s = c.steps[i], fast = s[0] === "skip";
        move(pts[i + 1], fast ? 420 : 640, () => {
          if (s[0] === "block") {
            verdict(i, s);
            for (let k = 0; k < 26; k++) { const a = Math.random() * 6.2832, v = 1 + Math.random() * 3; bits.push({ x: pk.x, y: pk.y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 1.5, a: 1 }); }
            pk = null; go();
            later(500, () => step(c.steps.length));
          } else if (s[0] === "ask") {
            pk.c = C.ask; verdict(i, ["ask", s[1]]); go();
            later(1500, () => { verdict(i, ["pass", "you approved it"]); pk.c = null; step(i + 1); });
          } else { verdict(i, s); later(fast ? 60 : 380, () => step(i + 1)); }
        });
      };
      step(0);
    });
  };
  picks.forEach((b) => b.addEventListener("click", () => { chosen = true; play(b.dataset.call); }));
  new ResizeObserver(() => { layout(); }).observe(field);
  new IntersectionObserver(([e]) => {
    const was = visible; visible = e.isIntersecting;
    if (visible && !was) { layout(); play(cur || ORDER[0]); }
    if (!visible) { timers.forEach(clearTimeout); timers = []; }
  }, { threshold: 0.35 }).observe(box);
  layout(); play(ORDER[0]);
})();

/* ---------- Questions: filter by topic, open and close smoothly ---------- */
(function faq() {
  const box = $(".faq");
  if (!box) return;
  const items = $$(".qa details", box), chips = $$(".faq-cats button", box);
  chips.forEach((c) => c.addEventListener("click", () => {
    chips.forEach((x) => x.setAttribute("aria-pressed", String(x === c)));
    items.forEach((d) => { d.hidden = c.dataset.cat !== "all" && d.dataset.cat !== c.dataset.cat; });
  }));
  if (reduce) return;
  for (const d of items) {
    const sum = $("summary", d), body = $(".qa-a", d);
    let anim = null;
    sum.addEventListener("click", (e) => {
      e.preventDefault();
      anim?.cancel();
      const opening = !d.open;
      if (opening) d.open = true;
      const h = body.scrollHeight;
      d.classList.toggle("closing", !opening);
      anim = body.animate(
        [{ height: opening ? "0px" : h + "px", opacity: opening ? 0 : 1 }, { height: opening ? h + "px" : "0px", opacity: opening ? 1 : 0 }],
        { duration: 320, easing: "cubic-bezier(0.16, 1, 0.3, 1)" },
      );
      anim.onfinish = () => { anim = null; if (!opening) d.open = false; d.classList.remove("closing"); };
    });
  }
})();

/* ---------- The Product menu: a glass panel under the bar, on hover or click ---------- */
(function mega() {
  const btn = $(".nav-drop"), panel = $("#mega");
  if (!btn || !panel) return;
  const wrap = btn.closest(".nav-menu");
  let t = 0;
  const set = (open) => { clearTimeout(t); panel.hidden = !open; btn.setAttribute("aria-expanded", String(open)); document.documentElement.classList.toggle("mega-open", open); };
  btn.addEventListener("click", () => set(panel.hidden));
  if (matchMedia("(hover: hover)").matches) {
    wrap.addEventListener("pointerenter", () => { clearTimeout(t); t = setTimeout(() => set(true), 80); });
    wrap.addEventListener("pointerleave", () => { clearTimeout(t); t = setTimeout(() => set(false), 180); });
  }
  if (matchMedia("(hover: hover)").matches) {
    panel.addEventListener("pointerenter", () => clearTimeout(t));
    panel.addEventListener("pointerleave", () => { clearTimeout(t); t = setTimeout(() => set(false), 180); });
  }
  panel.addEventListener("click", (e) => { if (e.target.closest("a")) set(false); });
  addEventListener("keydown", (e) => { if (e.key === "Escape" && !panel.hidden) { set(false); btn.focus(); } });
  document.addEventListener("pointerdown", (e) => { if (!panel.hidden && !wrap.contains(e.target) && !panel.contains(e.target)) set(false); });
})();

/* ---------- Smooth scrolling: the page glides to a stop instead of stepping ---------- */
(function smoothScroll() {
  if (reduce || typeof window.Lenis !== "function" || matchMedia("(pointer: coarse)").matches) return;
  const lenis = new window.Lenis({ lerp: 0.09, wheelMultiplier: 1, smoothWheel: true });
  window.__lenis = lenis;
  const raf = (t) => { lenis.raf(t); requestAnimationFrame(raf); };
  requestAnimationFrame(raf);
  // In-page links glide too, stopping clear of the floating bar.
  document.addEventListener("click", (e) => {
    const a = e.target.closest?.('a[href^="#"]');
    if (!a || e.defaultPrevented || e.metaKey || e.ctrlKey) return;
    const id = a.getAttribute("href").slice(1);
    const el = id ? document.getElementById(id) : null;
    if (!el && id !== "top" && id !== "") return;
    e.preventDefault();
    lenis.scrollTo(el && id !== "top" ? el : 0, { offset: -84, duration: 1.2 });
    history.replaceState(null, "", "#" + id);
  });
})();
